CREATE TABLE IF NOT EXISTS recursive_nodes (node_hash TEXT PRIMARY KEY, bot_name TEXT NOT NULL, node_type TEXT NOT NULL, source_uri TEXT NOT NULL, parent_hash TEXT, hop_depth INTEGER NOT NULL CHECK(hop_depth>=0), status TEXT NOT NULL CHECK(status IN ('leaf','has_links','depth_limit','blocked','error','cycle')), outbound_links_json TEXT NOT NULL, alien_seal TEXT NOT NULL, neila_seal TEXT NOT NULL, crawled_at TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_recursive_status ON recursive_nodes(status,hop_depth);